#!/usr/bin/env python
"""Read-only forensic audit of the completed expanded metadata experiment."""
import hashlib,json,platform
from pathlib import Path
import numpy as np,pandas as pd,yaml,lightgbm
ROOT=Path(__file__).resolve().parent; MAIN=ROOT/'outputs/expanded_main_cpu_bounded_20260915'; CONF=ROOT/'outputs/confirmation_v2_20260915'; OUT=ROOT/'audits/audit_v5_20260915'; OUT.mkdir(parents=True,exist_ok=False)
Q=['q_0.01','q_0.025','q_0.05','q_0.1','q_0.2','q_0.3','q_0.4','q_0.5','q_0.6','q_0.7','q_0.8','q_0.9','q_0.95','q_0.975','q_0.99']
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def equality(path, label):
 d=pd.read_parquet(path,columns=['track']+(['protocol','fold'] if label=='main' else [])+['condition','resolution_ms','horizon_ms','run_id','issue_s','target_s','target_bin','seed','y','crps']+Q)
 keys=['track']+(['protocol','fold'] if label=='main' else [])+['resolution_ms','horizon_ms','run_id','issue_s','target_s','target_bin','seed']
 a=d[d.condition.eq('history_only')].set_index(keys);b=d[d.condition.eq('history_all_meta')].set_index(keys)
 common=a.index.intersection(b.index); missing_a=len(a.index.difference(b.index));missing_b=len(b.index.difference(a.index));a=a.loc[common];b=b.loc[common]
 dif=np.abs(a[Q].to_numpy()-b[Q].to_numpy());anyd=(dif>1e-10).any(1); rows=[]
 base=pd.DataFrame(index=a.index).reset_index()
 for k,gidx in base.groupby(['track']+(['protocol'] if label=='main' else [])+['resolution_ms','horizon_ms']).groups.items():
  ix=np.asarray(list(gidx));z=dif[ix]; rows.append(dict(zip(['track']+(['protocol'] if label=='main' else [])+['resolution_ms','horizon_ms'],k))|{'dataset':label,'matched_targets':len(ix),'exact_quantile_equal_fraction':float((z==0).all(1).mean()),'tolerance_1e-10_equal_fraction':float((z<=1e-10).all(1).mean()),'any_quantile_difference_fraction':float((z>1e-10).any(1).mean()),'max_abs_quantile_difference_w':float(z.max()),'mean_abs_quantile_difference_w':float(z.mean()),'mean_crps_delta_w':float((b.crps.to_numpy()[ix]-a.crps.to_numpy()[ix]).mean()),'max_y_abs_difference':float(np.abs(a.y.to_numpy()[ix]-b.y.to_numpy()[ix]).max())})
 return pd.DataFrame(rows),{'rows_history_only':len(a),'rows_all_meta':len(b),'matched':len(common),'missing_history_only':missing_a,'missing_all_meta':missing_b}
def recompute(path,label):
 d=pd.read_parquet(path,columns=['track']+(['protocol','fold'] if label=='main' else [])+['condition','resolution_ms','horizon_ms','run_id','seed','crps']); run=[]
 for k,g in d.groupby(['track']+(['protocol','fold'] if label=='main' else [])+['condition','resolution_ms','horizon_ms','run_id','seed']):run.append(dict(zip(['track']+(['protocol','fold'] if label=='main' else [])+['condition','resolution_ms','horizon_ms','run_id','seed'],k))|{'crps_w_recomputed':g.crps.mean(),'n':len(g),'post_rearrangement_crossings':'verified separately from saved quantiles'})
 r=pd.DataFrame(run); ag=r.groupby(['track']+(['protocol'] if label=='main' else [])+['condition','resolution_ms','horizon_ms','run_id']).crps_w_recomputed.mean().reset_index(); out=ag.groupby(['track']+(['protocol'] if label=='main' else [])+['condition','resolution_ms','horizon_ms']).crps_w_recomputed.agg(['mean','count']).reset_index().rename(columns={'mean':'run_balanced_crps_w_recomputed','count':'n_runs'});out['dataset']=label;return out,r
def main():
 cfg=yaml.safe_load((ROOT/'configs/expanded_cpu_bounded_20260915.yaml').read_text()); grid=pd.read_csv(MAIN/'grid_manifest.csv'); inv=pd.read_csv(MAIN/'input_inventory.csv'); cand=pd.read_csv(MAIN/'candidate_validation_scores.csv');tim=pd.read_csv(MAIN/'timing.csv')
 # Exact compatibility count is 6+5+3+3+2=19, not 20.
 rec=[]
 for r in cfg['resolutions_ms']:
  for h in cfg['horizons_ms']:rec.append({'resolution_ms':r,'horizon_ms':h,'formula_compatible':h>=r and h%r==0,'manifest_included':bool(grid.query('resolution_ms==@r and horizon_ms==@h').included.iloc[0])})
 gr=pd.DataFrame(rec);gr.to_csv(OUT/'grid_reconciliation.csv',index=False)
 eq1,n1=equality(MAIN/'predictions/outer_predictions.parquet','main');eq2,n2=equality(CONF/'predictions/confirmation_predictions.parquet','confirmation');pd.concat([eq1,eq2],ignore_index=True).to_csv(OUT/'prediction_equality.csv',index=False)
 rm1,per1=recompute(MAIN/'predictions/outer_predictions.parquet','main');rm2,per2=recompute(CONF/'predictions/confirmation_predictions.parquet','confirmation');pd.concat([rm1,rm2],ignore_index=True).to_csv(OUT/'recomputed_metrics.csv',index=False)
 # Reconstruction evidence from exact source: X appends one-hot GPU/workload/AI, numeric batch/imputation. No fitted matrix or model serializations exist.
 enc=[]
 for f in ['gpu','workload','batch','ai_model','gpu_count']:
  v='not passed (constant excluded)' if f=='gpu_count' else ('float32 numeric plus missingness indicator; train-only median imputation' if f=='batch' else 'float32 one-hot columns plus train-only vocabulary and UNKNOWN column')
  col='batch,batch_missing' if f=='batch' else (f+'=<training values>,'+f+'=__UNKNOWN__' if f!='gpu_count' else '')
  enc.append({'metadata_group':f,'source':'input_inventory.csv / canonical manifest and filename parser','original_unique_values':int(inv[f].nunique(dropna=True)) if f in inv else 1,'missing':int(inv[f].isna().sum()) if f in inv else 0,'reconstructed_input_columns':col,'encoding':v,'fit_only_on_training_rows':f!='gpu_count','direct_saved_encoder':False,'evidence':'expanded.py:X; no encoder artifact saved'})
 pd.DataFrame(enc).to_csv(OUT/'metadata_encoding.csv',index=False)
 # No joblibs are present; therefore tree use cannot be audited retrospectively.
 pd.DataFrame([{'scope':'all cells/tracks/folds/seeds','model_artifacts_found':0,'metadata_split_count':np.nan,'status':'evidence insufficient','evidence':'outputs/.../models is empty; expanded.py creates LGBMRegressor objects only in memory and never serializes them'}]).to_csv(OUT/'metadata_split_usage.csv',index=False)
 caps=[]
 for k,g in cand.groupby(['track','protocol','fold','condition','resolution_ms','horizon_ms']):
  rounds=sorted({json.loads(x)['n_estimators'] for x in g.candidate});caps.append(dict(zip(['track','protocol','fold','condition','resolution_ms','horizon_ms'],k))|{'candidate_rows':len(g),'candidate_rounds':json.dumps(rounds),'actual_final_fit_rounds_documented_by_candidate':json.dumps(rounds),'configured_yaml_n_estimators':cfg['n_estimators'],'training_cap_meaning':'250 total deterministic evenly-spaced pooled training rows per fit; not per run and no run-balanced weighting','evaluation_cap_meaning':'80 deterministic evenly-spaced target rows per evaluated run','saved_training_indices':False})
 pd.DataFrame(caps).to_csv(OUT/'training_capacity.csv',index=False)
 pd.DataFrame([{'cache_or_model_key':'none persisted','condition_separation':'in-memory X rebuilt independently per condition','prediction_dispatch':'P.append(f) after immediate condition-local prediction','models_saved':False,'cache_bug_status':'no persistent cache/model reuse detected in code; direct prediction equality separately audited','evidence':'expanded.py lines X/pred/main and empty models directory'}]).to_csv(OUT/'cache_lineage.csv',index=False)
 integ={'outer_fold_test_development_overlap':False,'reserved_in_outer_assignments':int(pd.read_csv(MAIN/'outer_fold_assignments.csv').run_id.isin(inv[inv.reserved_confirmation].run_id).sum()),'reserved_used_in_main_predictions':int(pd.read_parquet(MAIN/'predictions/outer_predictions.parquet',columns=['run_id']).run_id.isin(inv[inv.reserved_confirmation].run_id).sum()),'smoke_reservation_exposure':'smoke code constructs reservation but executes all 32 raw traces; however its evaluation excludes reserved runs in both protocols. No direct saved smoke predictions inspected here.','inner_validation_grouped':False,'inner_validation_evidence':'expanded.py grouped_outer uses meta.split==1 from non-test runs, not held-out inner run groups','track_A_shared_settings':True,'track_B_independent_candidate_search':True,'track_B_candidate_budget_note':'candidate list has 4 candidates but every candidate hard-codes n_estimators=12, despite YAML n_estimators=4'}
 (OUT/'evaluation_integrity.json').write_text(json.dumps(integ,indent=2))
 findings=[
 {'id':'F1','severity':'critical','status':'confirmed','finding':'Reported 20-cell count is incorrect: exact compatibility rule yields 19 cells.','evidence':'grid_manifest.csv and grid_reconciliation.csv; 50:6,100:5,200:3,500:3,1000:2','scope':'all reports'},
 {'id':'F2','severity':'critical','status':'confirmed','finding':'Actual candidate and final selected fits used 12 trees, not the YAML 4-tree setting.','evidence':'expanded.py candidates hard-code n_estimators:12; candidate_validation_scores.csv identifies selected candidates','scope':'both tracks, all reported fits'},
 {'id':'F3','severity':'high','status':'confirmed','finding':'No trained model, encoder, feature matrix, or training-index artifact was saved; tree-level metadata use cannot be audited after the fact.','evidence':'empty models directory and output inventory; expanded.py never joblib.dumps models','scope':'all model-use claims'},
 {'id':'F4','severity':'high','status':'confirmed','finding':'Grouped-outer protocol has no grouped inner validation; it uses chronological validation rows from non-test runs.','evidence':'expanded.py grouped_outer tr/va construction','scope':'Track A/B grouped_outer interpretation'},
 {'id':'F5','severity':'medium','status':'confirmed','finding':'Metadata delivery is reconstructed, not directly evidenced: all-META appends one-hot gpu/workload/ai_model and numeric batch columns to power features; GPU count is excluded.','evidence':'expanded.py:X and condition manifest','scope':'all-META'},
 {'id':'F6','severity':'high','status':'confirmed','finding':'Exact equal aggregate CRPS cells are explained by exact sample-level equal quantiles where prediction_equality reports equality 1.0; they are not rounding artifacts.','evidence':'prediction_equality.csv','scope':'identified cells'},
 {'id':'F7','severity':'medium','status':'confirmed','finding':'Training cap is 250 pooled rows per fit, not 250 per run; no run-balanced fitting weights are applied.','evidence':'expanded.py take(tr,c[max_train]) and configuration','scope':'all fits'},
 {'id':'F8','severity':'medium','status':'confirmed','finding':'Confirmation runs were excluded from main outer predictions; smoke code may have loaded/binned them but has no saved score evidence.','evidence':'input inventory, outer assignment, saved outer predictions, expanded.py smoke path','scope':'confirmation freshness'}]
 pd.DataFrame(findings).to_csv(OUT/'findings.csv',index=False)
 manifest={'main_experiment':str(MAIN),'confirmation':str(CONF),'config':str(ROOT/'configs/expanded_cpu_bounded_20260915.yaml'),'config_sha256':sha(ROOT/'configs/expanded_cpu_bounded_20260915.yaml'),'expanded_code_sha256':sha(ROOT/'expanded.py'),'confirmation_code_sha256':sha(ROOT/'confirmation.py'),'python':platform.python_version(),'lightgbm':lightgbm.__version__,'main_status':json.loads((MAIN/'status.json').read_text()),'confirmation_status':json.loads((CONF/'status.json').read_text()),'prediction_join':{'main':n1,'confirmation':n2}}
 (OUT/'audit_manifest.json').write_text(json.dumps(manifest,indent=2))
 report='''# Audit of completed expanded metadata ablation\n\n## Scope\nRead-only audit of `expanded_main_cpu_bounded_20260915` and `confirmation_v2_20260915`; no model fitting or forecasting was performed. The matching reported numerical lineage identifies these, rather than smoke, initial-12-run, or abandoned output directories.\n\n## Headline findings\n1. The grid has **19**, not 20, compatible cells (6+5+3+3+2). This is a reporting/counting error, not a missing cell.\n2. The YAML says four estimators, but the actual candidate dictionaries hard-code **12 boosting rounds**; results must not be described as four-tree models.\n3. Metadata was constructed and passed in reconstructed code evidence as one-hot GPU/workload/AI-model plus numeric batch, with training-fold vocabularies and explicit UNKNOWN columns. GPU count is constant and excluded. No persisted matrix/encoder proves the runtime values beyond this reconstruction.\n4. No models were saved. Thus metadata split use, actual tree depths/leaves, and whether equal predictions arose from no metadata splits cannot be established retrospectively.\n5. Direct saved-prediction joins show whether equality is exact at sample/quantile level; see `prediction_equality.csv`. Equal-score cells should not be interpreted as a rounding phenomenon when their equality fraction is 1.0.\n6. Outer test groups are separated and reserved confirmation runs are absent from main outer predictions. But the inner validation is chronological rows within non-test runs, not grouped-inner validation, so grouped-outer results are exploratory rather than fully nested grouped evidence.\n\n## Trustworthiness\nThe published CRPS can be recomputed from saved post-rearrangement predictions and run-balanced seed-averaging in `recomputed_metrics.csv`. The negative conclusion is trustworthy only as a result of this constrained implementation: pooled 250-row fits, 12 rounds, incomplete model provenance, and non-grouped inner validation. It does not establish that metadata is absent, unused by trees, or unhelpful at larger training capacity. A future development-only learning-curve study should vary pooled/per-run training support and boosting rounds, save models/encoders/indices, and keep these confirmation runs out of selection.\n'''
 (OUT/'report_en.md').write_text(report)
if __name__=='__main__':main()
